(async function(){try{const b64=window.HH_PAYLOAD_B64||'';if(!b64)throw new Error('Academy payload is empty');const bin=atob(b64),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);const ds=new DecompressionStream('gzip');const text=await new Response(new Blob([u]).stream().pipeThrough(ds)).text();const data=JSON.parse(text);window.HH_COURSES=data.courses||[];window.HH_COURSE_BUNDLES=data.bundles||{};const s=document.createElement('script');s.src='/academy/runtime.js';s.onerror=()=>{document.body.insertAdjacentHTML('beforeend','<p style="padding:20px;color:#8e2b2b">Academy runtime failed to load.</p>')};document.body.appendChild(s)}catch(e){console.error(e);document.body.insertAdjacentHTML('beforeend','<p style="padding:20px;color:#8e2b2b">Academy learning materials could not be initialized.</p>')}})();